            background: #f6ffed;
            border: 1px solid #b7eb8f;
            color: #52c41a;
            padding: 12px;
            border-radius: 10px;
            text-align: center;
            margin-bottom: 20px;
            display: none;
        }

        .success-message.show {
            display: block;
        }

        .login-footer {
            text-align: center;
            margin-top: 24px;
            color: #999;
            font-size: 14px;
        }

        .login-footer a {
            color: #667eea;
            text-decoration: none;
        }

        .login-footer a:hover {
            text-decoration: underline;
        }
    </style>
</head>
<body>
    <div class="login-container">
        <div class="login-header">
            <h1>邮箱登录</h1>
            <p>欢迎使用邮箱账号登录</p>
        </div>

        <div class="success-message" id="successMessage">
            登录成功！正在跳转...
        </div>

        <form id="loginForm">
            <div class="form-group">
                <label for="email">邮箱地址</label>
                <input type="email" id="email" name="email" placeholder="请输入邮箱地址" autocomplete="email">
                <div class="error-message" id="emailError"></div>
            </div>

            <div class="form-group">
                <label for="password">密码</label>
                <input type="password" id="password" name="password" placeholder="请输入密码" autocomplete="current-password">
                <div class="error-message" id="passwordError"></div>
            </div>

            <div class="form-options">
                <label class="remember-me">
                    <input type="checkbox" id="rememberMe" name="rememberMe">
                    记住我
                </label>
                <a class="forgot-password" href="javascript:void(0);">忘记密码？</a>
            </div>

            <button type="submit" class="login-btn" id="loginBtn">登录</button>
        </form>

        <div class="login-footer">
            还没有账号？<a href="javascript:void(0);">立即注册</a>
        </div>
    </div>

    <script>
        const loginForm = document.getElementById('loginForm');
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const loginBtn = document.getElementById('loginBtn');
        const emailError = document.getElementById('emailError');
        const passwordError = document.getElementById('passwordError');
        const successMessage = document.getElementById('successMessage');

        // 邮箱格式验证
        function isValidEmail(email) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailRegex.test(email);
        }

        // 显示错误
        function showError(input, errorElement, message) {
            input.classList.add('error');
            errorElement.textContent = message;
            errorElement.classList.add('show');
        }

        // 清除错误
        function clearError(input, errorElement) {
            input.classList.remove('error');
            errorElement.classList.remove('show');
        }

        // 清除所有错误
        function clearAllErrors() {
            clearError(emailInput, emailError);
            clearError(passwordInput, passwordError);
        }

        // 实时验证 - 邮箱
        emailInput.addEventListener('input', function() {
            const email = this.value.trim();
            if (email) {
                if (!isValidEmail(email)) {
                    showError(this, emailError, '请输入正确的邮箱格式');
                } else {
                    clearError(this, emailError);
                }
            } else {
                clearError(this, emailError);
            }
        });

        // 实时验证 - 密码
        passwordInput.addEventListener('input', function() {
            const password = this.value;
            if (password) {
                clearError(this, passwordError);
            }
        });

        // 表单提交
        loginForm.addEventListener('submit', function(e) {
            e.preventDefault();
            clearAllErrors();
            successMessage.classList.remove('show');

            const email = emailInput.value.trim();
            const password = passwordInput.value;

            let hasError = false;

            // 验证邮箱
            if (!email) {
                showError(emailInput, emailError, '请输入邮箱地址');
                hasError = true;
            } else if (!isValidEmail(email)) {
                showError(emailInput, emailError, '请输入正确的邮箱格式');
                hasError = true;
            }

            // 验证密码
            if (!password) {
                showError(passwordInput, passwordError, '请输入密码');
                hasError = true;
            }

            if (hasError) {
                return;
            }

            // 模拟登录
            loginBtn.classList.add('loading');
            loginBtn.disabled = true;

            // 模拟网络请求延迟
            setTimeout(function() {
                loginBtn.classList.remove('loading');
                loginBtn.disabled = false;

                // 显示成功消息
                successMessage.textContent = '登录成功！正在跳转...';
                successMessage.classList.add('show');

                // 3秒后跳转（模拟）
                setTimeout(function() {
                    alert('登录成功！邮箱：' + email);
                    successMessage.classList.remove('show');
                    // 清空表单
                    loginForm.reset();
                }, 500);
            }, 1500);
        });

        // 回车键提交
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && e.target.tagName !== 'BUTTON') {
                loginForm.dispatchEvent(new Event('submit'));
            }
        });
    </script>
</body>
</html>
